    fail("created a zone with empty key name");
  } catch (IOException e) {
    assertExceptionContains("Must specify a key name when creating", e);
  }
  try {
    dfsAdmin.createEncryptionZone(zone2, null);
    fail("created a zone with null key name");
  } catch (IOException e) {
    assertExceptionContains("Must specify a key name when creating", e);
  }

