  dfsAdmin.createEncryptionZone(deepZone, TEST_KEY);
  assertNumZones(++numZones);
  assertZonePresent(null, deepZone.toString());

  // Create and list some zones to test batching of listEZ
  for (int i=1; i<6; i++) {
